"""Resilient client for the local order service.

- 401 -> fetch a fresh token and repeat the request
- 429 -> wait exactly as long as the service asks (Retry-After header / body), then repeat
- 5xx, connection errors, unparseable bodies -> back off briefly and repeat
- Every response is logged (one JSON line each) so behaviour can be audited afterwards.
- Gives up loudly (raises) after MAX_ATTEMPTS rather than ever returning partial data.
"""
import email.utils
import http.client
import json
import socket
import time
import urllib.error
import urllib.request

MAX_ATTEMPTS = 60


class GiveUp(Exception):
    pass


class Client:
    def __init__(self, base, log_path):
        self.base = base.rstrip("/")
        self.token = None
        self.log_f = open(log_path, "a")
        self.tokens_issued = 0
        self.counts = {}

    def _log(self, **kw):
        kw["t"] = round(time.time(), 3)
        self.log_f.write(json.dumps(kw) + "\n")
        self.log_f.flush()

    def _count(self, key):
        self.counts[key] = self.counts.get(key, 0) + 1

    def _raw(self, method, path, auth):
        req = urllib.request.Request(self.base + path, method=method, data=b"" if method == "POST" else None)
        if auth:
            req.add_header("Authorization", "Bearer %s" % self.token)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, {k.lower(): v for k, v in r.headers.items()}, r.read()
        except urllib.error.HTTPError as e:
            return e.code, {k.lower(): v for k, v in e.headers.items()}, e.read()

    @staticmethod
    def _retry_after(headers, body):
        waits = []
        h = headers.get("retry-after")
        if h is not None:
            h = h.strip()
            try:
                waits.append(float(h))
            except ValueError:
                try:
                    dt = email.utils.parsedate_to_datetime(h)
                    waits.append(max(0.0, dt.timestamp() - time.time()))
                except Exception:
                    pass
        try:
            b = json.loads(body)
            if isinstance(b, dict) and isinstance(b.get("retry_after"), (int, float)):
                waits.append(float(b["retry_after"]))
        except Exception:
            pass
        return max(waits) if waits else None

    def _request(self, method, path, auth, ok_statuses=(200,)):
        backoff = 0.5
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.refresh_token()
            try:
                status, headers, body = self._raw(method, path, auth)
            except (urllib.error.URLError, http.client.HTTPException, ConnectionError, socket.timeout, OSError) as e:
                self._count("conn_error")
                self._log(path=path, attempt=attempt, error=repr(e))
                time.sleep(backoff)
                backoff = min(backoff * 2, 8)
                continue
            self._count(str(status))
            entry = dict(path=path, attempt=attempt, status=status)
            if status not in ok_statuses or status != 200:
                entry["body"] = body[:500].decode("utf-8", "replace")
                entry["headers"] = {k: v for k, v in headers.items() if k in ("retry-after", "content-type", "www-authenticate")}
            self._log(**entry)

            if status in ok_statuses:
                if status != 200:
                    return status, None
                try:
                    return status, json.loads(body)
                except ValueError:
                    self._count("bad_json")
                    self._log(path=path, attempt=attempt, note="unparseable 200 body; retrying")
                    time.sleep(backoff)
                    backoff = min(backoff * 2, 8)
                    continue
            if status == 401 and auth:
                self.token = None  # expired / invalid -> new token on next loop
                continue
            if status == 429:
                wait = self._retry_after(headers, body)
                if wait is None:
                    wait = backoff
                    backoff = min(backoff * 2, 8)
                time.sleep(wait + 0.05)
                continue
            # 5xx or anything unexpected: back off and repeat
            time.sleep(backoff)
            backoff = min(backoff * 2, 8)
        raise GiveUp("%s %s failed after %d attempts" % (method, path, MAX_ATTEMPTS))

    def refresh_token(self):
        status, data = self._request("POST", "/token", auth=False)
        tok = data.get("token") if isinstance(data, dict) else None
        if not tok:
            raise GiveUp("token endpoint returned no token: %r" % (data,))
        self.token = tok
        self.tokens_issued += 1
        self._log(note="new token", token=tok)

    def get_json(self, path):
        return self._request("GET", path, auth=True)[1]

    def get_json_or_404(self, path):
        status, data = self._request("GET", path, auth=True, ok_statuses=(200, 404))
        return status, data

