"""Fetch every order page, following "next", and save each raw page to disk.

Usage: python3 -I fetch_orders.py <data_dir>
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from client import Client  # noqa: E402

REQUIRED = ("id", "customer_id", "status", "placed_at", "amount_cents")


def valid_page(data, expected_page):
    if not isinstance(data, dict):
        return "not an object"
    for k in ("page", "total_pages", "items", "next"):
        if k not in data:
            return "missing key %s" % k
    if data["page"] != expected_page:
        return "page mismatch: asked %s got %s" % (expected_page, data["page"])
    if not isinstance(data["items"], list):
        return "items not a list"
    for it in data["items"]:
        if not isinstance(it, dict) or any(k not in it for k in REQUIRED):
            return "malformed item %r" % (it,)
    return None


def main():
    data_dir = sys.argv[1]
    pages_dir = os.path.join(data_dir, "pages")
    os.makedirs(pages_dir, exist_ok=True)
    c = Client("http://localhost:8080", os.path.join(data_dir, "orders_log.jsonl"))

    path = "/orders?page=1"
    expected = 1
    seen_pages = []
    while path:
        # retry soft failures (200 but structurally wrong) a bounded number of times
        for soft_try in range(1, 11):
            data = c.get_json(path)
            problem = valid_page(data, expected)
            if problem is None:
                break
            c._log(path=path, soft_problem=problem)
            print("soft problem on %s (try %d): %s" % (path, soft_try, problem), flush=True)
        else:
            raise SystemExit("page %s kept failing validation" % path)
        with open(os.path.join(pages_dir, "page_%03d.json" % expected), "w") as f:
            json.dump(data, f)
        seen_pages.append((expected, data["total_pages"], len(data["items"]), data["next"]))
        print("page %d/%s items=%d next=%s" % (expected, data["total_pages"], len(data["items"]), data["next"]), flush=True)
        nxt = data["next"]
        if nxt is not None:
            if nxt != "/orders?page=%d" % (expected + 1):
                print("NOTE: unexpected next link %r after page %d" % (nxt, expected), flush=True)
            expected = int(nxt.split("page=")[1])
        path = nxt

    with open(os.path.join(data_dir, "pages_summary.json"), "w") as f:
        json.dump({"pages": seen_pages, "counts": c.counts, "tokens_issued": c.tokens_issued}, f, indent=1)
    print("done. response counts:", c.counts, "tokens issued:", c.tokens_issued)


if __name__ == "__main__":
    main()

