"""Fetch each customer referenced by a qualifying order exactly once; cache to customers.json.

Usage: python3 -I fetch_customers.py <data_dir>
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from client import Client  # noqa: E402
from common import load_listings, qualifies  # noqa: E402

REGIONS = {"north", "south", "east", "west"}


def problem_with(cid, rec):
    if not isinstance(rec, dict):
        return "not an object"
    if rec.get("id") != cid:
        return "id mismatch (%r)" % rec.get("id")
    if rec.get("region") not in REGIONS:
        return "bad region %r" % rec.get("region")
    d = rec.get("discount_pct")
    if not isinstance(d, int) or isinstance(d, bool) or not 0 <= d <= 100:
        return "bad discount_pct %r" % (d,)
    return None


def main():
    data_dir = sys.argv[1]
    cache_path = os.path.join(data_dir, "customers.json")
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path) as f:
            cache = json.load(f)
    orders, _, _ = load_listings(data_dir)
    needed = sorted({o["customer_id"] for o in orders.values() if qualifies(o)})
    print("customers needed:", len(needed), " already cached:", sum(1 for c in needed if c in cache))
    c = Client("http://localhost:8080", os.path.join(data_dir, "customers_log.jsonl"))
    not_found, odd = [], []
    for cid in needed:
        if cid in cache:
            continue
        for soft_try in range(1, 6):
            status, rec = c.get_json_or_404("/customers/%s" % cid)
            if status == 404:
                break
            prob = problem_with(cid, rec)
            if prob is None:
                break
            c._log(path="/customers/%s" % cid, soft_problem=prob)
            print("soft problem for %s (try %d): %s" % (cid, soft_try, prob), flush=True)
        if status == 404:
            not_found.append(cid)
            cache[cid] = None
        elif prob is not None:
            odd.append((cid, rec, prob))
            cache[cid] = rec
        else:
            cache[cid] = rec
        with open(cache_path, "w") as f:
            json.dump(cache, f, indent=1)
    print("404 customers:", not_found)
    print("customers with odd records:", odd)
    print("response counts:", c.counts, "tokens issued:", c.tokens_issued)


if __name__ == "__main__":
    main()

